#!/usr/bin/env python3
"""Compare proof-tactic counts for the three IrisITree benchmark variants.

The variants are counted directly:

* ``IrisITree`` contains the handwritten proofs;
* ``IrisITreeBubble`` contains the proofs that run ``ibubble``; and
* ``IrisITreeScript`` contains the scripts generated by ``ibubble?``.

Counts are lexical tactic-command counts inside ``:= by`` proof bodies, not
physical lines. Thus ``iapply foo; simp`` contributes one Iris tactic and one
Lean tactic. Bubble configuration such as ``simp`` in
``ibubble pureBy simp`` is counted only when it is a solver passed through
``pureBy``.
"""

from __future__ import annotations

import argparse
import csv
import json
import re
import sys
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Iterable, Sequence, TextIO


SOURCE_LAYERS = ("Core", "Effects", "HeapLang")
VARIANTS = (
    ("manual", "IrisITree"),
    ("search", "IrisITreeBubble"),
    ("generated", "IrisITreeScript"),
)

IRIS_TACTICS = (
    "ibubble",
    "iapply",
    "iassumption",
    "icases",
    "iclear",
    "icombine",
    "iexact",
    "iexists",
    "iframe",
    "ihave",
    "iinduction",
    "iintro",
    "ileft",
    "imod",
    "imodintro",
    "inext",
    "ipureintro",
    "irename",
    "irevert",
    "iright",
    "ispecialize",
    "isplit",
    "isplitl",
    "isplitr",
    "istart",
    "istop",
    "itrivial",
)

LEAN_TACTICS = (
    "aesop",
    "all_goals",
    "any_goals",
    "apply",
    "assumption",
    "by_cases",
    "by_contra",
    "case",
    "cases",
    "change",
    "clear",
    "congr",
    "constructor",
    "contradiction",
    "decide",
    "exact",
    "exact_mod_cast",
    "ext",
    "first",
    "focus",
    "funext",
    "generalize",
    "grind",
    "have",
    "induction",
    "infer_instance",
    "intro",
    "left",
    "linarith",
    "next",
    "norm_num",
    "obtain",
    "omega",
    "pick_goal",
    "rcases",
    "refine",
    "rename_i",
    "repeat",
    "rfl",
    "right",
    "ring",
    "rintro",
    "rotate_left",
    "rotate_right",
    "rw",
    "show",
    "simpa",
    "simp",
    "simp_all",
    "skip",
    "solve",
    "specialize",
    "split",
    "subst",
    "suffices",
    "trivial",
    "try",
    "unfold",
    "use",
)

IRIS_RE = re.compile(r"\b(?:" + "|".join(map(re.escape, IRIS_TACTICS)) + r")\b")
LEAN_RE = re.compile(r"\b(?:" + "|".join(map(re.escape, LEAN_TACTICS)) + r")\b")
IBUBBLE_RE = re.compile(r"\bibubble\??\b")
PURE_BY_RE = re.compile(r"\bpureBy\b")


@dataclass(frozen=True)
class TacticCounts:
    iris: int = 0
    lean: int = 0

    @property
    def total(self) -> int:
        return self.iris + self.lean

    def __add__(self, other: "TacticCounts") -> "TacticCounts":
        return TacticCounts(self.iris + other.iris, self.lean + other.lean)


@dataclass(frozen=True)
class VariantCounts:
    iris: int
    lean: int
    total: int
    ibubble_commands: int

    @classmethod
    def from_counts(cls, counts: TacticCounts, ibubble_commands: int) -> "VariantCounts":
        return cls(counts.iris, counts.lean, counts.total, ibubble_commands)


@dataclass(frozen=True)
class LayerMetrics:
    layer: str
    files: int
    manual: VariantCounts
    search: VariantCounts
    generated: VariantCounts

    @property
    def iris_reduction_percent(self) -> float:
        return reduction_percent(self.manual.iris, self.search.iris)

    @property
    def total_reduction_percent(self) -> float:
        return reduction_percent(self.manual.total, self.search.total)


@dataclass(frozen=True)
class ProofSource:
    active: tuple[str, ...]


def _leading_spaces(line: str) -> int:
    return len(line) - len(line.lstrip())


def extract_proof_source(text: str) -> ProofSource:
    """Extract active tactic text from ``:= by`` proof bodies."""

    active: list[str] = []
    in_proof = False
    waiting_for_body = False
    start_indent = 0
    body_indent: int | None = None

    def start_proof(line: str) -> bool:
        nonlocal in_proof, waiting_for_body, start_indent, body_indent
        code = line.split("--", 1)[0]
        if ":= by" not in code:
            return False
        start_indent = _leading_spaces(line)
        tail = code.split(":= by", 1)[1].strip()
        in_proof = True
        waiting_for_body = not bool(tail)
        body_indent = None
        if tail:
            active.append(tail)
        return True

    for line in text.splitlines():
        stripped = line.lstrip()
        indent = _leading_spaces(line)

        if not in_proof:
            start_proof(line)
            continue

        if not stripped or stripped.startswith("--"):
            continue

        if waiting_for_body:
            body_indent = indent
            waiting_for_body = False
            active.append(stripped.split("--", 1)[0])
            continue

        proof_ended = (
            body_indent is not None and indent < body_indent
        ) or (
            body_indent is None and indent <= start_indent
        )
        if proof_ended:
            in_proof = False
            waiting_for_body = False
            body_indent = None
            start_proof(line)
            continue

        active.append(stripped.split("--", 1)[0])

    return ProofSource(tuple(active))


def _plain_tactic_counts(text: str) -> TacticCounts:
    return TacticCounts(
        iris=len(IRIS_RE.findall(text)),
        lean=len(LEAN_RE.findall(text)),
    )


def _top_level_separator(text: str) -> tuple[int, int] | None:
    """Return the first top-level Lean tactic separator in ``text``."""

    opening = {"(": ")", "[": "]", "{": "}"}
    closing = set(opening.values())
    stack: list[str] = []
    in_string = False
    escaped = False
    index = 0

    while index < len(text):
        char = text[index]
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            index += 1
            continue
        if char == '"':
            in_string = True
        elif char in opening:
            stack.append(opening[char])
        elif char in closing:
            if stack and char == stack[-1]:
                stack.pop()
        elif not stack and text.startswith("<;>", index):
            return index, index + 3
        elif not stack and char == ";":
            return index, index + 1
        index += 1

    return None


def _top_level_config_keyword(text: str, start: int) -> int:
    """Find where a ``pureBy`` solver ends and Bubble configuration resumes."""

    opening = {"(": ")", "[": "]", "{": "}"}
    closing = set(opening.values())
    stack: list[str] = []
    index = start

    while index < len(text):
        char = text[index]
        if char in opening:
            stack.append(opening[char])
        elif char in closing:
            if stack and char == stack[-1]:
                stack.pop()
        elif not stack:
            for keyword in ("with", "without", "pureStop"):
                end = index + len(keyword)
                if (
                    text.startswith(keyword, index)
                    and (index == 0 or not (text[index - 1].isalnum() or text[index - 1] == "_"))
                    and (end == len(text) or not (text[end].isalnum() or text[end] == "_"))
                ):
                    return index
        index += 1

    return len(text)


def _pure_solver_counts(configuration: str) -> TacticCounts:
    result = TacticCounts()
    cursor = 0
    while match := PURE_BY_RE.search(configuration, cursor):
        start = match.end()
        end = _top_level_config_keyword(configuration, start)
        result += _plain_tactic_counts(configuration[start:end])
        cursor = end
        if cursor >= len(configuration):
            break
    return result


def count_tactics(text: str) -> TacticCounts:
    """Classify tactics in one source fragment, including Bubble automation."""

    match = IBUBBLE_RE.search(text)
    if match is None:
        return _plain_tactic_counts(text)

    before = text[:match.start()]
    after = text[match.end():]
    separator = _top_level_separator(after)
    if separator is None:
        configuration = after
        suffix = ""
    else:
        separator_start, separator_end = separator
        configuration = after[:separator_start]
        suffix = after[separator_end:]

    return (
        _plain_tactic_counts(before)
        + TacticCounts(iris=1)
        + _pure_solver_counts(configuration)
        + count_tactics(suffix)
    )


def sum_counts(fragments: Iterable[str]) -> TacticCounts:
    result = TacticCounts()
    for fragment in fragments:
        result += count_tactics(fragment)
    return result


def analyze_layer(folder: Path) -> VariantCounts:
    counts = TacticCounts()
    ibubble_commands = 0
    for source_file in sorted(folder.glob("*.lean")):
        proof = extract_proof_source(source_file.read_text(encoding="utf-8"))
        counts += sum_counts(proof.active)
        ibubble_commands += sum(len(IBUBBLE_RE.findall(line)) for line in proof.active)
    return VariantCounts.from_counts(counts, ibubble_commands)


def combine_counts(counts: Iterable[VariantCounts]) -> VariantCounts:
    values = tuple(counts)
    return VariantCounts(
        iris=sum(value.iris for value in values),
        lean=sum(value.lean for value in values),
        total=sum(value.total for value in values),
        ibubble_commands=sum(value.ibubble_commands for value in values),
    )


def reduction_percent(baseline: int, reduced: int) -> float:
    return 0.0 if baseline == 0 else 100.0 * (baseline - reduced) / baseline


def analyze(root: Path) -> list[LayerMetrics]:
    variant_roots = {name: root / directory for name, directory in VARIANTS}
    missing = [str(path) for path in variant_roots.values() if not path.is_dir()]
    if missing:
        raise SystemExit("missing case-study variants: " + ", ".join(missing))

    rows: list[LayerMetrics] = []
    for layer in SOURCE_LAYERS:
        relative_files: dict[str, set[str]] = {}
        for variant, variant_root in variant_roots.items():
            layer_root = variant_root / layer
            if not layer_root.is_dir():
                raise SystemExit(f"missing source layer: {layer_root}")
            relative_files[variant] = {path.name for path in layer_root.glob("*.lean")}
        if len({frozenset(files) for files in relative_files.values()}) != 1:
            details = "; ".join(
                f"{variant}={sorted(files)}" for variant, files in relative_files.items()
            )
            raise SystemExit(f"variant file mismatch in {layer}: {details}")

        rows.append(LayerMetrics(
            layer=layer,
            files=len(relative_files["manual"]),
            manual=analyze_layer(variant_roots["manual"] / layer),
            search=analyze_layer(variant_roots["search"] / layer),
            generated=analyze_layer(variant_roots["generated"] / layer),
        ))

    rows.append(LayerMetrics(
        layer="TOTAL",
        files=sum(row.files for row in rows),
        manual=combine_counts(row.manual for row in rows),
        search=combine_counts(row.search for row in rows),
        generated=combine_counts(row.generated for row in rows),
    ))
    total = rows[-1]
    if total.manual.ibubble_commands or total.generated.ibubble_commands:
        raise SystemExit(
            "expected ibubble commands only in IrisITreeBubble, found "
            f"manual={total.manual.ibubble_commands}, "
            f"generated={total.generated.ibubble_commands}"
        )
    return rows


def render_table(rows: Sequence[LayerMetrics]) -> str:
    headers = (
        "Layer", "Files", "Commands",
        "Manual I", "Search I", "I reduction", "Generated I",
        "Manual all", "Search all", "All reduction", "Generated all",
    )
    values = [(
        row.layer,
        str(row.files),
        str(row.search.ibubble_commands),
        str(row.manual.iris),
        str(row.search.iris),
        f"{row.iris_reduction_percent:.1f}%",
        str(row.generated.iris),
        str(row.manual.total),
        str(row.search.total),
        f"{row.total_reduction_percent:.1f}%",
        str(row.generated.total),
    ) for row in rows]
    widths = [
        max(len(headers[index]), *(len(row[index]) for row in values))
        for index in range(len(headers))
    ]

    def render(row: Sequence[str]) -> str:
        return "  ".join(
            value.ljust(widths[index]) if index == 0 else value.rjust(widths[index])
            for index, value in enumerate(row)
        )

    return "\n".join((
        render(headers),
        "  ".join("-" * width for width in widths),
        *(render(row) for row in values),
    ))


def row_as_dict(row: LayerMetrics) -> dict[str, object]:
    return {
        "layer": row.layer,
        "files": row.files,
        "search_commands": row.search.ibubble_commands,
        "manual": asdict(row.manual),
        "search": asdict(row.search),
        "generated": asdict(row.generated),
        "iris_reduction_percent": row.iris_reduction_percent,
        "total_reduction_percent": row.total_reduction_percent,
    }


def render_csv(rows: Sequence[LayerMetrics], stream: TextIO) -> None:
    writer = csv.writer(stream, lineterminator="\n")
    writer.writerow((
        "layer", "files", "search_commands",
        "manual_iris", "search_iris", "iris_reduction_percent", "generated_iris",
        "manual_all", "search_all", "all_reduction_percent", "generated_all",
    ))
    for row in rows:
        writer.writerow((
            row.layer,
            row.files,
            row.search.ibubble_commands,
            row.manual.iris,
            row.search.iris,
            f"{row.iris_reduction_percent:.6f}",
            row.generated.iris,
            row.manual.total,
            row.search.total,
            f"{row.total_reduction_percent:.6f}",
            row.generated.total,
        ))


def build_argument_parser() -> argparse.ArgumentParser:
    default_root = Path(__file__).resolve().parent.parent
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root",
        type=Path,
        default=default_root,
        help=f"directory containing all three variants (default: {default_root})",
    )
    output = parser.add_mutually_exclusive_group()
    output.add_argument("--json", action="store_true", help="emit JSON")
    output.add_argument("--csv", action="store_true", help="emit CSV")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_argument_parser().parse_args(argv)
    rows = analyze(args.root)
    if args.json:
        print(json.dumps([row_as_dict(row) for row in rows], indent=2))
    elif args.csv:
        render_csv(rows, sys.stdout)
    else:
        print(render_table(rows))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
